import {describe, expect, it} from '@jest/globals';
import {createChatOrchestrator} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk, SendMessageParams} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

const SENT_AT = '2026-01-01T00:00:00.000Z';

function session(): ChatSession {
  return {sessionId: 's1', userId: 'u1', entries: [{role: 'user', content: 'hi', timestamp: SENT_AT}]};
}

function silentProvider(): AIProvider {
  return {
    async *sendMessage(_p: SendMessageParams): AsyncGenerator<MessageChunk> {
      yield {type: 'text', text: 'ok'};
      yield {type: 'stop', stopReason: 'end_turn'};
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
}

const promptBuilder = new PromptBuilder({identity: 'sys'});

// specs/hal-engine-config-hooks/spec.md#beforeSession-throws-onError
describe('chatOrchestrator beforeSession error handling', () => {
  it('calls onError with the thrown error when beforeSession throws', async () => {
    const boom = new Error('beforeSession failed');
    let captured: Error | undefined;

    const orchestrator = createChatOrchestrator(silentProvider(), promptBuilder, undefined, {
      hooks: {
        beforeSession: async () => {
          throw boom;
        },
        onError: async (_session, error) => {
          captured = error;
        },
      },
    });

    let thrownError: unknown;
    await orchestrator.processMessage(session()).catch((e: unknown) => {
      thrownError = e;
    });
    expect({thrownError, captured}).toEqual({thrownError: boom, captured: boom});
  });
});
